# The Stan model and the independent NumPyro implementation must define the
# same posterior. Stan's `~` statements drop normalising constants, so the test
# compares the log-density difference between two parameter points, which does
# not depend on those constants. The fixture is synthetic and generated by
# tests/make_stan_parity_fixture.py in the repository root.
test_that("Stan and NumPyro log densities agree", {
  skip_if_no_stan()
  f <- fixture("numpyro_parity.json")
  sd <- f$stan_data
  int_fields <- c("C", "R", "A_max", "N_EY", "N_K1", "MU_ANCHOR", "N_K5", "N_SERIES", "N_WAVE", "N_A", "N_S",
                  "region_of_country", "A_country", "A_region", "A_age", "A_ey_idx",
                  "S_country", "S_age", "S_ey_idx", "S_series", "S_wave")
  for (k in int_fields) sd[[k]] <- as.integer(sd[[k]])
  fit0 <- suppressWarnings(rstan::sampling(oosc_stan_model(), data = sd, chains = 0))
  points <- jsonlite::fromJSON(test_path("fixtures", "numpyro_parity.json"), simplifyVector = FALSE)$points
  # nested JSON arrays -> R vectors, matrices and arrays (first index outermost, as in NumPy)
  as_r <- function(x) jsonlite::fromJSON(jsonlite::toJSON(x, auto_unbox = TRUE, digits = NA))
  lp <- vapply(points, function(pt) {
    p <- lapply(pt, as_r)
    rstan::log_prob(fit0, rstan::unconstrain_pars(fit0, p), adjust_transform = FALSE)
  }, numeric(1))
  expect_equal(lp[1] - lp[2], f$numpyro_log_density[1] - f$numpyro_log_density[2], tolerance = 1e-9)
})
